<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/css/app.css"><style>body{background:#f5f7fb}.page{max-width:1100px;margin:auto;padding:28px 18px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:20px;box-shadow:0 8px 30px rgba(15,23,42,.06)}.search{display:flex;gap:10px}.search input{flex:1;padding:13px;border:1px solid #dbe1ea;border-radius:10px}.btn{display:inline-block;border:0;border-radius:10px;padding:12px 17px;background:#2563eb;color:#fff;text-decoration:none;font-weight:700}.secondary{background:#eef2f7;color:#0f172a}.table-wrap{overflow:auto;margin-top:18px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:13px 10px;border-bottom:1px solid #edf0f4;white-space:nowrap}.badge{padding:5px 9px;border-radius:999px;background:#ecfdf5;color:#047857;font-size:12px}.muted{color:#64748b}@media(max-width:650px){.top{align-items:flex-start;flex-direction:column}.search{flex-direction:column}}</style><title>Search Customer · ISPLUKA</title></head><body><main class="page"><div class="top"><div><h1>Search Customer</h1><p class="muted">Find subscribers by name, phone, email or customer code.</p></div><a class="btn secondary" href="/">Dashboard</a></div><section class="card"><div class="search"><input id="q" placeholder="Search customer…" autofocus><button class="btn" id="go">Search</button></div><div class="table-wrap"><table><thead><tr><th>Code</th><th>Customer</th><th>Phone</th><th>Area</th><th>Status</th><th>Action</th></tr></thead><tbody id="rows"><tr><td colspan="6" class="muted">Enter a search term.</td></tr></tbody></table></div></section></main><script>const q=document.getElementById('q'),go=document.getElementById('go'),rows=document.getElementById('rows');async function run(){const s=q.value.trim();rows.innerHTML='<tr><td colspan="6">Searching…</td></tr>';const r=await fetch('/api/customers?search='+encodeURIComponent(s)+'&per_page=50');const j=await r.json();const items=j.data?.items||[];rows.innerHTML=items.map(c=>`<tr><td><strong>${esc(c.customer_code)}</strong></td><td>${esc(c.name)}</td><td>${esc(c.phone||'—')}</td><td>${esc(c.area||'—')}</td><td><span class="badge">${esc(c.status)}</span></td><td><a href="/api/customer?id=${c.id}" class="btn secondary">View</a></td></tr>`).join('')||'<tr><td colspan="6" class="muted">No customer found.</td></tr>'}go.onclick=run;q.addEventListener('keydown',e=>{if(e.key==='Enter')run()});function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}</script></body></html>